// Trail lines per system, generated by the hand-run scripts/trail-lines.ts
// into data/trail-lines.json (Google-encoded polylines). Its own chunk: the
// maps import this lazily so pins and tiles never wait for it.

import data from "../../../data/trail-lines.json";
import type { LatLon } from "./geo";
import { decodePolyline } from "./polyline";

const ENCODED = (data as { lines: Record<string, string[]> }).lines;
const decoded = new Map<string, LatLon[][]>();

/** The trail's lines, decoded once; empty when the trail has none. */
export function trailLines(id: string): LatLon[][] {
  let lines = decoded.get(id);
  if (!lines) {
    lines = (ENCODED[id] ?? []).map(decodePolyline);
    decoded.set(id, lines);
  }
  return lines;
}
